// Ekspor data mahasiswa yang bersih dari duplikasi '(Akun Lama)'
export const mahasiswaData: Mahasiswa[] = rawMahasiswaData.filter((item) => {
  const prodi = String(item.program_studi || '');
  const fak = String(item.fakultas || '');
  return !prodi.includes('(Akun Lama)') && !fak.includes('(Akun Lama)');
});
